function renderCoachHome(){const host=document.querySelector('[data-coach-home]');if(!host)return;const state=loadState();if(!state.assessment){host.innerHTML='<div class="coach-status"><span class="coach-step">YOUR FIRST STEP</span><strong>Find your starting point</strong><p>Choose the future you want, then complete a short DraMap level check.</p></div><a class="button red coach-primary" href="'+absolute('assessment/')+'"><span>Start free assessment</span><small>About 3 minutes · no account</small></a>';return;}document.body.classList.add('has-study-plan');const plan=dailyPlan(state),route=plan.route,goal=goalFor(state),count=(state.sessions||[]).length,streak=state.learning?.streak?.count||0,label=plan.comeback?'WELCOME BACK · 3 MIN RESTART':plan.due.length?'REVIEW READY · '+plan.due.length+' ITEM'+(plan.due.length===1?'':'S'):'TODAY · '+plan.minutes+' MIN · '+streak+' DAY CHAIN';document.querySelectorAll('.future-hero-image img,.mobile-future-image img').forEach(image=>{image.src=absolute(goal.image);image.alt=goal.title;});document.querySelectorAll('.future-caption strong,.mobile-future-image strong').forEach(copy=>copy.textContent=goal.title+'.');host.innerHTML='<div class="coach-status"><span class="coach-step">'+label+'</span><strong>'+route.title+'</strong><p>'+plan.why+'</p></div><a class="button red coach-primary" href="'+webRouteURL(route)+'"><span>'+(plan.comeback?'Restart with 3 minutes':route.mode==='review'?'Start due review':'Start today\'s plan')+'</span><small>One tap · '+count+' session'+(count===1?'':'s')+' saved</small></a>';const detail=document.createElement('section');detail.className='today-prescription';detail.innerHTML='<div class="today-prescription-head"><div><span class="coach-step">YOUR '+plan.minutes+' MINUTE PLAN</span><h2>Do these in order</h2></div><a href="'+absolute('roadmap/')+'">View roadmap</a></div><div class="today-steps">'+plan.steps.map((step,index)=>'<article><b>0'+(index+1)+'</b><span><strong>'+step.label+'</strong><small>'+step.copy+'</small></span><em>'+step.minutes+'m</em></article>').join('')+'</div><div class="habit-cue"><span><b>Make starting automatic.</b> Open this page after your usual '+(state.habitCue||'daily break')+'.</span><button type="button" data-cue>Set my cue</button></div><a class="quick-start" href="'+absolute(route.href)+'?quick=1">Low-energy day? Just open a 3-minute round →</a>';host.insertAdjacentElement('afterend',detail);detail.querySelector('[data-cue]').addEventListener('click',()=>showCuePicker(state));}

function showCuePicker(state){const overlay=document.createElement('div');overlay.className='coach-modal';overlay.innerHTML='<section><span class="coach-step">YOUR DAILY CUE</span><h2>When is opening this site easiest?</h2><p>Keep your normal routine. Attach Japanese to something you already do.</p><div class="cue-options"><button data-cue-value="morning coffee">After morning coffee</button><button data-cue-value="lunch break">After lunch</button><button data-cue-value="commute">During my commute</button><button data-cue-value="evening wind-down">Before relaxing at night</button></div><button class="modal-close" data-close>Not now</button></section>';document.body.appendChild(overlay);overlay.querySelectorAll('[data-cue-value]').forEach(button=>button.addEventListener('click',()=>{state.habitCue=button.dataset.cueValue;saveState(state);location.reload();}));overlay.querySelector('[data-close]').addEventListener('click',()=>overlay.remove());}

