function showDraMapImportNotice(imported){if(!imported)return;const state=loadState(),daily=state.bridgeSummary||{},result=daily.todayAnswered?daily.todayAnswered+' answers · '+daily.todayAccuracy+'% correct'+(daily.todayWeak?' · '+daily.todayWeak+' focus':''):'Your goal and today’s course are ready here.',notice=document.createElement('aside');notice.className='dramap-import-notice';notice.innerHTML='<div><span>DRAMAP STUDY CONNECTED</span><strong>'+result+'</strong></div><a href="'+absolute('progress/')+'">Continue my plan →</a><button type="button" aria-label="Close">×</button>';document.body.appendChild(notice);notice.querySelector('button').addEventListener('click',()=>notice.remove());}

function guestTransferURL(state){const route=recommendedRoute(state),summary=guestProgressSummary(state),params=new URLSearchParams({from:'transfer',course:route.course,level:state.assessment?.estimatedLevel||'Foundation',goal:state.profile?.goal||'daily',minutes:String(todayMinutes(state)),streak:String(summary.streak),answered:String(summary.answered),sessions:String(summary.sessions)});if(summary.weak)params.set('weak',summary.weak);return absolute('')+'?'+params.toString();}
function addGuestContinuityCard(){const state=loadState(),host=document.querySelector('[data-progress-dashboard],[data-roadmap]');if(!host||!state.assessment)return;const card=document.createElement('section');card.className='guest-continuity';card.innerHTML='<div><span class="coach-step">NO ACCOUNT NEEDED</span><h2>Your plan is saved on this device.</h2><p>Keep learning without signing in. Only use the transfer button when you actually want this plan on another phone or computer.</p></div><div><button type="button" data-transfer>Move this plan to another device</button><small data-transfer-status>Automatic account sync can wait until you need it.</small></div>';host.appendChild(card);card.querySelector('[data-transfer]').addEventListener('click',async()=>{const url=guestTransferURL(state),status=card.querySelector('[data-transfer-status]');try{if(navigator.share)await navigator.share({title:'My Japanese Training Lab plan',url});else await navigator.clipboard.writeText(url);status.textContent=navigator.share?'Plan ready to open on your other device.':'Transfer link copied. Open it on your other device.';}catch(_){status.innerHTML='<a href="'+url+'">Open the transfer link</a> and copy it from the address bar.';}});}

function addDraMapHandoff(){if(document.documentElement.dataset.dramapHandoff)return;document.documentElement.dataset.dramapHandoff='ready';document.addEventListener('click',event=>{const link=event.target.closest&&event.target.closest('a[href^="adventure3d2://"]');if(!link)return;event.preventDefault();const href=link.href,params=new URL(href).searchParams,course=(params.get('course')||'today’s Japanese plan').replace(/_/g,' ');window.location.href=href;window.setTimeout(()=>{if(document.visibilityState!=='visible'||document.querySelector('.dramap-handoff'))return;const layer=document.createElement('div');layer.className='dramap-handoff';layer.innerHTML='<section><button class="dramap-handoff-close" type="button" aria-label="Close">×</button><span class="coach-step">CONTINUE WITHOUT LOSING YOUR PLACE</span><h2>DraMap did not open?</h2><p>Your <b data-dramap-course></b> plan is ready. If DraMap is already installed, try again. Otherwise download it, then return to this page.</p><div class="dramap-handoff-actions"><a class="button red" data-dramap-retry>Try opening DraMap again</a><a class="button gold" href="'+DRAMAP_URL+'">Download DraMap for iOS</a><button type="button" data-dramap-web>Keep learning on the web</button></div><small>No account is required. This page keeps your current Web progress on this device.</small></section>';layer.querySelector('[data-dramap-course]').textContent=course;layer.querySelector('[data-dramap-retry]').href=href;const close=()=>layer.remove();layer.querySelector('.dramap-handoff-close').addEventListener('click',close);layer.querySelector('[data-dramap-web]').addEventListener('click',close);layer.addEventListener('click',e=>{if(e.target===layer)close();});document.body.appendChild(layer);},1400);});}

function renderAssessment(){
  const host=document.querySelector('[data-assessment]');if(!host)return;
  let setupStep=0,questionIndex=0,correct=0,timer=20,timerId=null;const answers=[];const profile={goal:'',minutes:10,weeklyTarget:5,selfLevel:''};
  const setup=[
    {key:'goal',label:'What future do you want in Japanese?',options:[['Understand manga & anime','anime'],['Work and do business in Japan','work'],['Make Japanese friends','friends'],['Play games in Japanese','games'],['Reach my JLPT goal','jlpt']]},
    {key:'minutes',label:'How much time can you usually study?',options:[['5 minutes',5],['10 minutes',10],['15 minutes',15],['30 minutes',30],['60 minutes',60],['120 minutes',120],['180 minutes',180]]},
    {key:'weeklyTarget',label:'How many days should your coach plan for?',options:[['3 days — gentle',3],['5 days — steady',5],['7 days — intensive',7]]},
    {key:'selfLevel',label:'Which description feels closest?',options:[["I'm starting",'new'],['I know some Japanese','some'],['I already study for the JLPT','jlpt']]}
  ];
  function progress(percent,text){host.querySelector('[data-assessment-progress]').style.width=percent+'%';host.querySelector('[data-assessment-count]').textContent=text;}
  function shell(){host.innerHTML='<div class="diagnostic-top"><span data-assessment-count></span><button type="button" class="text-button" data-restart>Start over</button></div><div class="assessment-progress"><span data-assessment-progress></span></div><section class="diagnostic-card" data-diagnostic-card></section>';host.querySelector('[data-restart]').addEventListener('click',()=>{clearInterval(timerId);setupStep=questionIndex=correct=0;answers.length=0;renderSetup();});}
  function renderSetup(){clearInterval(timerId);const item=setup[setupStep],isGoal=item.key==='goal';progress((setupStep/(setup.length+placementQuestions.length))*100,'SETUP '+(setupStep+1)+' OF '+setup.length);host.querySelector('[data-diagnostic-card]').innerHTML='<div class="eyebrow">Build your study plan</div><h2>'+item.label+'</h2><div class="diagnostic-choices '+(isGoal?'goal-choices':'')+'">'+item.options.map(([label,value])=>'<button class="diagnostic-choice" data-value="'+value+'">'+(isGoal?'<img src="'+absolute(goalProfiles[value].image)+'" alt="">':'')+'<span>'+label+'</span><b>›</b></button>').join('')+'</div>';host.querySelectorAll('[data-value]').forEach(button=>button.addEventListener('click',()=>{profile[item.key]=['minutes','weeklyTarget'].includes(item.key)?Number(button.dataset.value):button.dataset.value;setupStep+=1;setupStep<setup.length?renderSetup():renderTestIntro();}));}
  function renderTestIntro(){progress((setup.length/(setup.length+placementQuestions.length))*100,'LEVEL CHECK');host.querySelector('[data-diagnostic-card]').innerHTML='<div class="eyebrow">DraMap placement test</div><h2>Now check what you can recognize.</h2><p class="diagnostic-lead">Eight questions move from Hiragana to N1. Each has a 20-second limit. It is fine not to know an answer.</p><button class="button red diagnostic-start" type="button">Start level check</button>';host.querySelector('.diagnostic-start').addEventListener('click',renderQuestion);}
  function renderQuestion(){if(questionIndex>=placementQuestions.length)return finish();const item=placementQuestions[questionIndex];timer=20;progress(((setup.length+questionIndex)/(setup.length+placementQuestions.length))*100,'QUESTION '+(questionIndex+1)+' OF '+placementQuestions.length+' · '+item.level.toUpperCase());const context=item.context&&item.context!==item.answer?'<div class="diagnostic-context">'+item.context+'</div>':'';host.querySelector('[data-diagnostic-card]').innerHTML='<div class="diagnostic-question-head"><span>'+item.prompt+'</span><b data-timer>20s</b></div>'+context+'<div class="diagnostic-choices">'+item.choices.map(value=>'<button class="diagnostic-choice" data-answer="'+value+'"><span>'+value+'</span><b>›</b></button>').join('')+'</div>';const startedAt=Date.now();timerId=setInterval(()=>{timer-=1;const el=host.querySelector('[data-timer]');if(el)el.textContent=timer+'s';if(timer<=0)selectAnswer('',startedAt);},1000);host.querySelectorAll('[data-answer]').forEach(button=>button.addEventListener('click',()=>selectAnswer(button.dataset.answer,startedAt)));}
  function selectAnswer(value,startedAt){clearInterval(timerId);const item=placementQuestions[questionIndex];const isCorrect=value===item.answer;if(isCorrect)correct+=1;answers.push({level:item.level,skill:item.skill,correct:isCorrect,responseMs:Date.now()-startedAt});host.querySelectorAll('[data-answer]').forEach(button=>{button.disabled=true;if(button.dataset.answer===item.answer)button.classList.add('correct');else if(button.dataset.answer===value)button.classList.add('wrong');});setTimeout(()=>{questionIndex+=1;renderQuestion();},650);}
  function finish(){progress(100,'YOUR STARTING PLAN');const reachedIndex=Math.max(0,Math.min(routesOrder.length-1,Math.floor((correct/placementQuestions.length)*routesOrder.length)));const estimatedLevel=routesOrder[reachedIndex],route=routes[estimatedLevel],skills={};answers.forEach(a=>{const s=skills[a.skill]||(skills[a.skill]={correct:0,total:0});s.total++;if(a.correct)s.correct++;});const state=loadState();state.profile=profile;state.assessment={estimatedLevel,recommendedCourse:route.course,correct,total:placementQuestions.length,confidence:Math.round((.5+Math.abs(correct/placementQuestions.length-.5))*100),skills,completedAt:new Date().toISOString()};saveState(state);try{localStorage.setItem(LEGACY_PROGRESS_KEY,JSON.stringify({title:'Start at '+estimatedLevel,body:route.reason,href:absolute(route.href),completedAt:state.assessment.completedAt}));}catch(_){}host.querySelector('[data-diagnostic-card]').innerHTML='<div class="result-level"><span>RECOMMENDED START</span><strong>'+estimatedLevel+'</strong></div><div class="result-copy"><h2>'+route.title+'</h2><p>'+route.reason+'</p><div class="result-facts"><span><b>'+correct+'/'+placementQuestions.length+'</b> correct</span><span><b>'+profile.minutes+' min</b> daily plan</span><span><b>Saved</b> on this device</span></div><a class="button red coach-primary" href="'+absolute(route.href)+'"><span>Start my first session</span><small>'+profile.minutes+'-minute plan</small></a><a class="button gold coach-primary" href="'+dramapPlanURL(route.course,state,route.item)+'"><span>Open this plan in DraMap</span><small>Level, goal and study time included</small></a><a class="text-link" href="'+absolute('progress/')+'">See my complete plan</a> · <a class="text-link" href="'+DRAMAP_URL+'">Download the app</a></div>';}
  shell();renderSetup();
}

function renderProgressDashboard(){const dashboard=document.querySelector('[data-progress-dashboard]');if(!dashboard)return;const state=loadState();if(!state.assessment){dashboard.innerHTML='<article class="plan-empty"><span>STEP 1</span><h2>Build your personal route</h2><p>Take the DraMap placement test and receive one clear starting course.</p><a class="button red" href="'+absolute('assessment/')+'">Start assessment</a></article>';return;}const route=recommendedRoute(state),score=Math.round((state.assessment.correct/state.assessment.total)*100),sessionList=state.sessions||[],sessions=sessionList.length,loggedMinutes=Math.round(sessionList.reduce((sum,item)=>sum+Number(item.durationSeconds||0),0)/60),due=dueRecords(state),weak=weakestSkill(state),streak=state.learning?.streak?.count||0,courseValues=Object.values(state.learning?.courses||{}),attempts=courseValues.reduce((sum,item)=>sum+(item.attempts||0),0),correct=courseValues.reduce((sum,item)=>sum+(item.correct||0),0),accuracy=attempts?Math.round(correct*100/attempts):null,weakLabel=weak?weak[0].replace(/^./,value=>value.toUpperCase()):'Collecting data',weakAccuracy=weak?Math.round(weak[1].correct*100/weak[1].attempts):null;dashboard.innerHTML='<section class="plan-today"><div><span class="coach-step">'+(due.length?'REVIEW READY NOW':'TODAY · '+todayMinutes(state)+' MINUTES')+'</span><h2>'+route.title+'</h2><p>'+route.reason+'</p></div><a class="button gold coach-primary" href="'+webRouteURL(route)+'"><span>'+(due.length?'Start '+due.length+' due review'+(due.length===1?'':'s'):'Start today\'s session')+'</span><small>'+(due.length?'Strengthen it before it fades':'Continue your recommended route')+'</small></a></section><section class="plan-overview"><article><span>DAILY CHAIN</span><strong>'+streak+' day'+(streak===1?'':'s')+'</strong><p>'+sessions+' completed session'+(sessions===1?'':'s')+(loggedMinutes?' · '+loggedMinutes+' min logged':'')+'</p></article><article><span>TRAINING ACCURACY</span><strong>'+(accuracy===null?'—':accuracy+'%')+'</strong><p>'+(attempts?attempts+' answers measured':'Complete a training set to begin')+'</p></article><article><span>NEXT REVIEW</span><strong>'+(due.length?due.length+' ready':'On schedule')+'</strong><p>10 min · 1 d · 3 d · 7 d spacing</p></article></section><section class="coach-insight"><div><span class="coach-step">COACH INSIGHT</span><h2>'+(weak?'Focus on '+weakLabel:'Your coach is learning with you')+'</h2><p>'+(weak?'Your measured '+weakLabel.toLowerCase()+' accuracy is '+weakAccuracy+'%. The next plan will keep this skill in the loop until it becomes stable.':'Answer inside a course and the plan will identify your weakest skill automatically.')+'</p></div><strong>'+(weak?weakAccuracy+'%':'START')+'</strong></section><section class="plan-roadmap"><div class="roadmap-item done"><b>1</b><span><strong>Placement complete</strong><small>'+state.assessment.estimatedLevel+' starting point · '+score+'% score</small></span></div><div class="roadmap-item current"><b>2</b><span><strong>'+route.title+'</strong><small>'+(due.length?'Spaced review is the priority now':'Current training focus')+'</small></span></div><div class="roadmap-item"><b>3</b><span><strong>Automatic review</strong><small>Misses return sooner; stable answers wait longer</small></span></div><div class="roadmap-item app"><b>4</b><span><strong>Continue in DraMap</strong><small>Keep Japanese one tap away on iPhone</small></span><a href="'+DRAMAP_URL+'">Get the app</a></div></section>';}
function renderFocusPrescription(){const dashboard=document.querySelector('[data-progress-dashboard]'),state=loadState();if(!dashboard||!state.assessment)return;const totals={};Object.entries(state.assessment.skills||{}).forEach(([skill,value])=>totals[skill]={attempts:value.total||0,correct:value.correct||0});Object.values(state.learning?.courses||{}).forEach(course=>Object.entries(course.skills||{}).forEach(([skill,value])=>{const item=totals[skill]||(totals[skill]={attempts:0,correct:0});item.attempts+=value.attempts||0;item.correct+=value.correct||0;}));const courses=currentLevelCourses(state),pickCourse=skill=>skill==='kanji'?courses.find(id=>id.includes('kanji')):skill==='vocabulary'?courses.find(id=>id.includes('vocabulary')||id==='basic_words'):skill==='grammar'?courses.find(id=>id.includes('grammar')):skill==='pronunciation'?courses.find(id=>id==='hiragana'||id==='katakana'):courses.find(id=>id.includes('grammar'))||courses[0],measured=Object.entries(totals).filter(([,value])=>value.attempts>0).sort((a,b)=>(a[1].correct/a[1].attempts)-(b[1].correct/b[1].attempts)),fallback=['reading','vocabulary','grammar'].map(skill=>[skill,{attempts:0,correct:0}]),priorities=[...measured,...fallback].filter(([skill],index,array)=>array.findIndex(item=>item[0]===skill)===index).slice(0,3).map(([skill,value])=>{const id=pickCourse(skill)||courses[0],route=courseRoutes[id],accuracy=value.attempts?Math.round(value.correct*100/value.attempts):null;return{skill,id,route,accuracy,attempts:value.attempts};}),month=(state.sessions||[]).filter(item=>daysSince(item.completedAt)<30),activeDays=new Set(month.map(item=>new Date(item.completedAt).toLocaleDateString('en-CA'))).size,minutes=Math.round(month.reduce((sum,item)=>sum+Number(item.durationSeconds||0),0)/60),minutesLabel=minutes?String(minutes):month.some(item=>Number(item.durationSeconds||0)>0)?'<1':'0',section=document.createElement('section');section.className='coach-report';section.innerHTML='<div class="coach-report-head"><div><span class="coach-step">YOUR 30-DAY COACH REPORT</span><h2>What to strengthen next</h2><p>Every completed lesson updates this order. Start with number one; the coach will rebalance it as your results change.</p></div><div class="month-stats"><span><b>'+activeDays+'</b>active days</span><span><b>'+month.length+'</b>sessions</span><span><b>'+minutesLabel+'</b>minutes</span></div></div><div class="focus-queue">'+priorities.map((item,index)=>'<article><b>0'+(index+1)+'</b><div><span>'+item.skill.toUpperCase()+(item.accuracy===null?' · BUILD A BASELINE':' · '+item.accuracy+'%')+'</span><h3>'+item.route.title+'</h3><p>'+(item.accuracy===null?'Complete one short set so the coach can measure this skill.':item.accuracy<70?'This is the current bottleneck. Keep the next set short and accurate.':'Keep this skill in rotation until it becomes automatic.')+'</p></div><div class="focus-actions"><a href="'+absolute(item.route.href)+'">Start on web →</a><a class="focus-app" href="'+dramapPlanURL(item.id,state)+'">Open in DraMap</a></div></article>').join('')+'</div>';dashboard.querySelector('.coach-insight')?.insertAdjacentElement('afterend',section);}
function reviewTime(dueAt){const distance=dueAt-Date.now();if(distance<=0)return'Due now';const minutes=Math.ceil(distance/60000);if(minutes<60)return'In '+minutes+' min';const hours=Math.ceil(minutes/60);if(hours<24)return'In '+hours+' hr';const days=Math.ceil(hours/24);return'In '+days+' day'+(days===1?'':'s');}
function renderReviewCenter(){const host=document.querySelector('[data-review-center]');if(!host)return;const state=loadState();if(!state.assessment){host.innerHTML='<article class="plan-empty"><span>STEP 1</span><h2>Build your review schedule</h2><p>Take the placement test, then every finished lesson will schedule its own return.</p><a class="button red" href="'+absolute('assessment/')+'">Start assessment</a></article>';return;}const records=(state.learning?.records||[]).filter(record=>record.dueAt&&routeForCourse(record.courseId)).sort((a,b)=>a.dueAt-b.dueAt),due=records.filter(record=>record.dueAt<=Date.now()),upcoming=records.filter(record=>record.dueAt>Date.now()).slice(0,8),fallback=recommendedRoute(state);if(!records.length){host.innerHTML='<section class="review-empty"><span class="coach-step">YOUR REVIEW QUEUE IS READY</span><h2>Finish one short lesson to start the cycle.</h2><p>Rate it Hard, Good or Easy. The coach will bring it back at the right time instead of asking you to remember when.</p><div><a class="button red" href="'+absolute(fallback.href)+'">Start '+fallback.title+'</a><a class="button gold" href="'+dramapPlanURL(fallback.course,state)+'">Open in DraMap</a></div></section>';return;}const card=record=>{const route=courseRoutes[record.courseId],item=record.item==='session-summary'?'Course checkpoint':String(record.item||'Practice item').replace(/[_-]+/g,' '),href=absolute(route.href)+'?review=1&item='+encodeURIComponent(record.item||'session');return'<article class="review-card '+(record.dueAt<=Date.now()?'due':'upcoming')+'"><div><span>'+reviewTime(record.dueAt)+' · '+String(record.skill||'mixed').toUpperCase()+'</span><h3>'+route.title+'</h3><p>'+item+' · '+(record.lapses||0)+' miss'+((record.lapses||0)===1?'':'es')+'</p></div><div class="review-actions"><a href="'+href+'">Review on web →</a><a class="review-app" href="'+dramapPlanURL(record.courseId,state,record.item||'session')+'">Open in DraMap</a></div></article>';};host.innerHTML='<section class="review-summary"><div><span class="coach-step">SPACED REVIEW COACH</span><h2>'+(due.length?due.length+' review'+(due.length===1?' is':'s are')+' ready now':'Nothing is due yet')+'</h2><p>'+(due.length?'Start at the top. The shortest overdue memory comes first.':'Your next reviews are already scheduled. Continue today’s course instead of studying everything again.')+'</p></div><div><b>'+due.length+'</b><span>READY</span></div></section>'+(due.length?'<section class="review-group"><div class="review-group-head"><span>DO THESE FIRST</span><small>'+due.length+' due</small></div>'+due.map(card).join('')+'</section>':'<section class="review-clear"><b>✓</b><div><strong>Review queue clear</strong><span>Keep the habit easy today.</span></div><a href="'+absolute(fallback.href)+'">Continue '+fallback.title+' →</a></section>')+(upcoming.length?'<section class="review-group"><div class="review-group-head"><span>COMING UP</span><small>The coach will unlock these automatically</small></div>'+upcoming.map(card).join('')+'</section>':'')+'<section class="review-footer"><div><span class="coach-step">KEEP REVIEWS ONE TAP AWAY</span><h2>Use the same schedule in DraMap.</h2><p>Open today’s recommended course in the app, then return here whenever you want the full queue.</p></div><a class="button gold" href="'+dramapPlanURL(fallback.course,state)+'">Continue in DraMap</a></section>';}
function renderGoalMilestones(){const state=loadState();if(!state.assessment)return;const goal=goalFor(state),position=levelPosition(state),steps=goalMilestones[state.profile?.goal]||goalMilestones.daily,route=recommendedRoute(state),section=document.createElement('section');section.className='goal-milestones';section.innerHTML='<div class="goal-milestones-intro"><img src="'+absolute(goal.image)+'" alt="'+goal.title+'"><div><span class="coach-step">YOUR FUTURE, BROKEN INTO REAL STEPS</span><h2>'+goal.title+'</h2><p>You are at step '+(position+1)+' of 4. Keep today small; the route below shows what that practice is building toward.</p></div></div><div class="milestone-track">'+steps.map((copy,index)=>{const labels=milestoneLabels(index);return'<article class="'+(index<position?'complete':index===position?'current':'future')+'"><b>'+(index<position?'✓':'0'+(index+1))+'</b><span>'+labels[0]+' · '+labels[1]+'</span><strong>'+copy+'</strong><small>'+(index<position?'Foundation checked':index===position?'Your current training zone':'A later outcome')+'</small></article>';}).join('')+'</div><div class="milestone-actions"><span>Today: <b>'+route.title+'</b></span><a href="'+TIKTOK_URL+'">See Japanese with Yuji ↗</a><a class="button gold" href="'+dramapPlanURL(route.course,state,route.item)+'">Continue in DraMap</a></div>';const dashboard=document.querySelector('[data-progress-dashboard]'),roadmap=document.querySelector('[data-roadmap]');if(dashboard){const goalCard=dashboard.querySelector('.goal-reminder');(goalCard||dashboard.querySelector('.plan-today'))?.insertAdjacentElement('afterend',section);}else if(roadmap){roadmap.prepend(section);}}
function enhanceGoalDashboard(){const dashboard=document.querySelector('[data-progress-dashboard]'),state=loadState();if(!dashboard||!state.assessment)return;const goal=goalFor(state),route=recommendedRoute(state),sessions=state.sessions||[],activeDates=new Set(sessions.map(item=>new Date(item.completedAt).toLocaleDateString('en-CA'))),days=Array.from({length:7},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(6-index));const key=date.toLocaleDateString('en-CA');return{label:date.toLocaleDateString('en',{weekday:'short'}).slice(0,1),active:activeDates.has(key),today:index===6};});const goalCard=document.createElement('section');goalCard.className='goal-reminder';goalCard.innerHTML='<img src="'+absolute(goal.image)+'" alt="'+goal.title+'"><div><span class="coach-step">WHY YOU STARTED</span><h2>'+goal.title+'</h2><p>'+goal.copy+' Today\'s '+route.title+' session is one small move toward that future.</p><div class="goal-links"><a href="'+absolute('assessment/')+'">Change my goal</a><a href="'+TIKTOK_URL+'">Learn with Yuji ↗</a><a href="'+DRAMAP_URL+'">Open DraMap ↗</a></div></div>';dashboard.querySelector('.plan-today')?.insertAdjacentElement('afterend',goalCard);const rhythm=document.createElement('section');rhythm.className='habit-rhythm';rhythm.innerHTML='<div><span class="coach-step">YOUR LAST 7 DAYS</span><h2>Keep the start easy.</h2><p>Do not catch up. Open the course after your '+(state.habitCue||'usual daily break')+' and finish one small round.</p><a class="quick-start" href="'+absolute(route.href)+'?quick=1">I only have 3 minutes — start anyway →</a></div><div class="habit-days">'+days.map(day=>'<div class="'+(day.active?'active ':'')+(day.today?'today':'')+'"><span>'+day.label+'</span><b>'+(day.active?'✓':'·')+'</b></div>').join('')+'</div>';dashboard.appendChild(rhythm);const plan=weeklyPlan(state),week=document.createElement('section');week.className='weekly-plan';week.innerHTML='<div class="weekly-plan-head"><div><span class="coach-step">YOUR NEXT 7 DAYS</span><h2>Follow the plan. Skip the decisions.</h2><p>The coach mixes your current level, weakest skill and reviews. Miss a day? Continue with today instead of catching up.</p></div><a href="'+absolute('roadmap/')+'">See the full route →</a></div><div class="weekly-plan-days">'+plan.map(day=>'<article class="'+(day.index===0?'today ':'')+(day.completed?'complete':'')+'"><span>'+(day.index===0?'TODAY':day.date.toLocaleDateString('en',{weekday:'short'}).toUpperCase())+'</span><b>'+day.date.getDate()+'</b><h3>'+day.route.title+'</h3><p>'+(day.review?'Review + short training':'One focused training round')+'</p><a href="'+absolute(day.route.href)+(day.review?'?review=1':'')+'">'+(day.completed?'Practice again':'Start')+' →</a></article>').join('')+'</div><div class="weekly-plan-footer"><span>Keep Japanese one tap away between sessions.</span><a href="'+TIKTOK_URL+'">Yuji on TikTok ↗</a><a class="button gold" href="'+DRAMAP_URL+'">Get DraMap for iOS</a></div>';dashboard.appendChild(week);}
function enhanceCourseCatalog(){const main=document.querySelector('main');if(!main||!document.querySelector('.course-levels'))return;const state=loadState(),route=recommendedRoute(state),guide=document.createElement('section');guide.className='catalog-guide wrap';guide.innerHTML=state.assessment?'<div><span class="coach-step">YOUR RECOMMENDED START</span><h2>'+route.title+'</h2><p>'+route.reason+'</p></div><a class="button red coach-primary" href="'+absolute(route.href)+'"><span>Continue my plan</span><small>One clear next step</small></a>':'<div><span class="coach-step">NOT SURE WHERE TO START?</span><h2>Let DraMap choose your first course.</h2><p>A short placement test turns this full catalog into one personal route.</p></div><a class="button red coach-primary" href="'+absolute('assessment/')+'"><span>Find my level</span><small>About 3 minutes</small></a>';main.querySelector('.page-hero')?.insertAdjacentElement('afterend',guide);}
function addCoachPulse(){if(document.querySelector('.coach-pulse')||location.pathname.includes('/learn/'))return;const header=document.querySelector('.site-header'),state=loadState(),pulse=document.createElement('section');pulse.className='coach-pulse';if(!state.assessment){pulse.innerHTML='<div><span>YOUR COACH IS READY</span><strong>First, find the right starting point.</strong></div><a href="'+absolute('assessment/')+'">Check my level · 3 min →</a>';}else{const route=recommendedRoute(state),today=new Date().toLocaleDateString('en-CA'),done=(state.sessions||[]).some(item=>new Date(item.completedAt).toLocaleDateString('en-CA')===today),days=new Set((state.sessions||[]).filter(item=>daysSince(item.completedAt)<7).map(item=>new Date(item.completedAt).toLocaleDateString('en-CA'))).size,target=Number(state.profile?.weeklyTarget||5);pulse.classList.toggle('is-done',done);pulse.innerHTML='<div><span>'+(done?'TODAY COMPLETE · COME BACK TOMORROW':'TODAY’S ONE NEXT STEP')+'</span><strong>'+(done?'Your review timing is saved.':route.title)+'</strong><small>'+days+'/'+target+' active days this week</small></div><div class="coach-pulse-actions">'+(done?'<a href="'+TIKTOK_URL+'">Watch Yuji on TikTok ↗</a>':'<a href="'+webRouteURL(route)+'">Start now →</a>')+'<a class="pulse-app" href="'+dramapPlanURL(route.course,state,route.item)+'">Open in DraMap</a></div>';}header?.insertAdjacentElement('afterend',pulse);}
function addGlobalPromotionDock(){if(document.querySelector('.global-promo-dock'))return;const state=loadState(),route=recommendedRoute(state),promoStyles=document.createElement('link');promoStyles.rel='stylesheet';promoStyles.href=new URL('promo.css?v=2026102108',scriptUrl).href;document.head.appendChild(promoStyles);const dock=document.createElement('aside');dock.className='global-promo-dock';dock.setAttribute('aria-label','Learn Japanese with Yuji and DraMap');dock.innerHTML='<div class="promo-person"><img src="'+absolute('assets/yuji-shimizu.jpg')+'" alt="Yuji Shimizu"><span><strong>Learn with Yuji</strong><small>Japanese from Japan</small></span></div><div class="promo-actions"><a class="promo-tiktok" href="https://www.tiktok.com/@yuji.shimizu2" target="_blank" rel="noopener noreferrer"><span>WATCH &amp; LEARN</span><strong>TikTok ↗</strong></a><a class="promo-dramap" href="'+(state.assessment?dramapPlanURL(route.course,state,route.item):DRAMAP_URL)+'"><span>CONTINUE IN THE APP</span><strong>'+(state.assessment?'Open today’s plan ↗':'Get DraMap ↗')+'</strong></a></div>';document.body.appendChild(dock);}
const importedFromDraMap=importDraMapPlan();addProgressNavigation();addCoachPulse();renderCoachHome();renderAssessment();renderProgressDashboard();renderFocusPrescription();renderReviewCenter();enhanceGoalDashboard();renderWeeklyCoach();renderRoadmap();renderGoalMilestones();enhanceCourseCatalog();addGuestContinuityCard();addGlobalPromotionDock();addMobileCoachNav();addSmartAppBanner();addDraMapHandoff();showDraMapImportNotice(importedFromDraMap);
